//! The 16-bit interpolation steps under every float mode (the reference
//! driver's InterpolationModes test, rows measured on hardware): p1 (f32
//! result, as v_interp_p1ll_f16 and v_interp_p1lv_f16 compute it) and p2
//! (f16 result) of (delta, coordinate, base) with f32 and f16 denormals
//! flushed or kept and IEEE_MODE off or on.

use ps5shader::interp::Machine;
use ps5shader::ssa::InterpParam;
use ps5shader::testing::asm::*;
use ps5shader::testing::IoTest;
use ps5shader::translate::FloatMode;

const fn vop3_w0(op: u32, dst: u32) -> u32 {
    0xD400_0000 | op << 16 | dst
}
const fn vop3_w1(src0: u32, src1: u32, src2: u32) -> u32 {
    src0 | src1 << 9 | src2 << 18
}

const MODE_NAMES: [&str; 8] = [
    "IEEE=0 f32-flush f16-flush",
    "IEEE=0 f32-flush f16-keep",
    "IEEE=0 f32-keep f16-flush",
    "IEEE=0 f32-keep f16-keep",
    "IEEE=1 f32-flush f16-flush",
    "IEEE=1 f32-flush f16-keep",
    "IEEE=1 f32-keep f16-flush",
    "IEEE=1 f32-keep f16-keep",
];
const OP_NAMES: [&str; 3] = ["p1 (v_interp_p1ll_f16)", "v_interp_p2_f16", "p1 (v_interp_p1lv_f16)"];

/// (delta, coordinate, base) of the three steps; the expected results per
/// mode (f32 bits for p1, f16 bits for p2).
type Row = ([u32; 9], [[u32; 3]; 8]);

