/// The float mode of mode index `k`: bit 0 keeps f16 denormals, bit 1 f32
/// denormals, bit 2 IEEE_MODE.
fn float_mode(k: usize) -> FloatMode {
    let f32_keep = if k & 2 != 0 { 3 << 4 } else { 0 };
    let f16_keep = if k & 1 != 0 { 3 << 6 } else { 0 };
    FloatMode { mode: f32_keep | f16_keep, ieee: k & 4 != 0, ..FloatMode::default() }
}

/// v4 = coordinate 0, v5 = coordinate 1, v2 = the p2 base (a partial
/// sum), v7 = coordinate 2; v8 = p1 of attr0.x, v9 = p2 of attr0.x and v2,
/// v10 = p1 of attr0.x.high; stored at output[0..3].
fn run(row: &[u32; 9], mode: FloatMode) -> Vec<u32> {
    let mut code = vec![
        vop1(OP_V_MOV_B32, 4, 255),
        row[1],
        vop1(OP_V_MOV_B32, 5, 255),
        row[4],
        vop1(OP_V_MOV_B32, 2, 255),
        row[5],
        vop1(OP_V_MOV_B32, 7, 255),
        row[7],
        vop1(OP_V_MOV_B32, 9, inline_u32(0)),
    ];
    code.extend([vop3_w0(0x342, 8), vop3_w1(0, 256 + 4, 0)]);
    code.extend([vop3_w0(0x35A, 9), vop3_w1(0, 256 + 5, 256 + 2)]);
    code.extend([vop3_w0(0x342, 10), vop3_w1(0x100, 256 + 7, 0)]);
    for (k, reg) in [8u32, 9, 10].into_iter().enumerate() {
        code.extend(mubuf(OP_BUFFER_STORE_DWORD, reg, 0, 1, inline_u32(0), k as u32 * 4, true, false, false));
    }
    code.push(S_ENDPGM);
    let t = IoTest::new(&code, 1, 3).with_float_mode(mode);
    let (ib, ob) = (t.input_base, t.output_base);
    let row = *row;
    let setup = move |m: &mut Machine| {
        m.memory.write_words(ib, &[0; 3]);
        m.memory.write_words(ob, &[0xDEAD_BEEF; 3]);
        m.interp = Some(Box::new(move |_, _, p, _| {
            f32::from_bits(match p {
                InterpParam::HalfP10 { high: false } => row[0],
                InterpParam::HalfP0 { high: false } => row[2],
                InterpParam::HalfP20 { high: false } => row[3],
                InterpParam::HalfP10 { high: true } => row[6],
                InterpParam::HalfP0 { high: true } => row[8],
                _ => 0x7FC0_0000,
            })
        }));
    };
    let m = t.run.run_checked(&setup, &[(ob, 3)]).unwrap();
    m.memory.read_words(ob, 3)
}

#[test]
fn interpolation_modes_match_hardware_rows() {
    let mut failures = Vec::new();
    for (k, name) in MODE_NAMES.iter().enumerate() {
        for (r, (input, expected)) in ROWS.iter().enumerate() {
            let out = run(input, float_mode(k));
            for op in 0..3 {
                if out[op] != expected[k][op] {
                    failures.push(format!("{}, {name}, row {r}: got {:#010x}, expected {:#010x}", OP_NAMES[op], out[op], expected[k][op]));
                }
            }
        }
    }
    let n = failures.len();
    failures.truncate(24);
    assert!(n == 0, "{n} mismatches:\n{}", failures.join("\n"));
}
